"use server";

import { serverAction } from "rwsdk/worker";

export type Todo = {
  id: string;
  title: string;
};

const todos: Todo[] = [];

export function getTodos(): Todo[] {
  return todos;
}

export function resetTodos(): void {
  todos.length = 0;
}

export function removeTodo(id: string): void {
  const idx = todos.findIndex((t) => t.id === id);
  if (idx >= 0) {
    todos.splice(idx, 1);
  }
}

export const addTodo = serverAction(async (formData: FormData) => {
  const title = String(formData.get("title") || "").trim();
  if (!title) {
    return;
  }
  const newTodo: Todo = {
    id: crypto.randomUUID(),
    title,
  };
  todos.push(newTodo);
  return;
});

export const deleteTodo = serverAction(async (id: string) => {
  removeTodo(id);
  return;
});

export const deleteTodoForm = serverAction(async (formData: FormData) => {
  const id = String(formData.get("id") || "");
  if (id) {
    removeTodo(id);
  }
  return;
});
